<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Concerns\HasUuids; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo;
class TransferQuote extends Model { use HasUuids; public $incrementing=false; protected $keyType='string'; protected $fillable=['quote_reference','user_id','source_wallet_currency_account_id','beneficiary_id','beneficiary_account_id','source_currency_code','destination_currency_code','source_amount_minor','recipient_amount_minor','provider_fee_minor','platform_fee_minor','exchange_rate','fx_quote_reference','corridor_status','status','sandbox_only','expires_at','metadata']; protected $casts=['sandbox_only'=>'boolean','expires_at'=>'datetime','metadata'=>'array']; public function isExpired(): bool { return now()->greaterThanOrEqualTo($this->expires_at); } public function beneficiary(): BelongsTo { return $this->belongsTo(Beneficiary::class); } public function user(): BelongsTo { return $this->belongsTo(User::class); } public function sourceAccount(): BelongsTo { return $this->belongsTo(WalletCurrencyAccount::class,'source_wallet_currency_account_id'); } }
